            }

            run("KMCP_INDEX") {
                script "../../../kmcp/index/main.nf"
                process {
                    """
                    input[0] = KMCP_COMPUTE.out.outdir
                    input[1] = [
                        [id: 'taxdmp'],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/metagenome/nodes.dmp', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/metagenome/names.dmp', checkIfExists: true)
                        ]
                    ]
                    input[2] = channel.of("MT192765.1\t2697049").collectFile(name: "genome2taxid.map", newLine: true).map{ mapfile -> [[id: 'genome2taxid'], mapfile]}
                    """
                }
            }

            run("KMCP_SEARCH") {
                script "../../../kmcp/search/main.nf"
                process {
                    """
                    input[0] = [
                                    [id:'test', single_end:true ], // meta map
